title: "TEXT"
---
railroad-ebnf-beta
  TEXT term ( ( "+" | "-" ) term )* ;
  term = TEXT ( ( "*" | "/" ) TEXT )* ;
  TEXT = TEXT | "(" expression ")" ;
  TEXT = TEXT+ ;
  signed = ("+" | "-")? TEXT ;

---
title: "TEXT"
---
railroad-abnf-beta
  TEXT TEXT "TEXT" TEXT ;
  TEXT = 1*( ALPHA / DIGIT / "." / "-" ) ;
  TEXT = label *( "." label ) ;

---
title: "TEXT"
---
railroad-abnf-beta
  TEXT 2*4TEXT ;
  TEXT = 3ALPHA *DIGIT ;
  TEXT = [ "." 1*8ALPHA ] ;

---
title: "TEXT"
---
railroad-peg-beta
  TEXT <- TEXT (("+" / "-") TEXT)* ;
  TEXT <- TEXT (("*" / "/") TEXT)* ;
  TEXT <- Number / "(" TEXT ")" ;
  Number <- TEXT+ ;

---
title: "TEXT"
---
railroad-peg-beta
  # Keywords are excluded from identifiersTEXT
  TEXT <- TEXT TEXT Letter Letter* ;
  Keyword <- "if" / "else" / "while" ;
  Letter <- "a" / "b" / "_" / TEXT ;

